A for loop allows you to repeat a block of code a specific number of times. Widely used when the number of iterations is known in advance. Makes it easy to iterate over arrays, lists, or sequences, generate number series, and perform repetitive tasks efficiently.
            C++

    #include <iostream>
using namespace std;

int main() {
    for(int i = 1; i <= 5; i++) {
        cout << i << " ";
    }
    cout << endl;
    return 0;
}


            C

    #include <stdio.h>

int main() {
    for(int i = 1; i <= 5; i++) {
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}


            Java

    public class ForLoopExample {
    public static void main(String[] args) {
        for(int i = 1; i <= 5; i++) {
            System.out.print(i + " ");
        }
        System.out.println();
    }
}


            Python

    for i in range(1, 6):
