    using System;

class Program {
    static void Main() {
        for (int i = 1; i <= 5; i++) {
            Console.Write(i + " ");
        }
        Console.WriteLine();
    }
}


            JavaScript

    for(let i = 1; i <= 5; i++) {
    console.log(i);
}

